var extraCopy={fr:['HT / portion','Utiliser ce prix','Objectif de contribution'],en:['excl. tax / portion','Use this price','Contribution target'],es:['sin IVA / ración','Usar este precio','Objetivo de contribución'],it:['IVA esclusa / porzione','Usa questo prezzo','Obiettivo contributo'],de:['netto / Portion','Diesen Preis verwenden','Beitragsziel'],nl:['excl. btw / portie','Deze prijs gebruiken','Bijdragedoel'],pt:['sem IVA / porção','Usar este preço','Meta de contribuição']};keys=keys.concat(['perPortion','usePrice','target']);Object.keys(copy).forEach(function(k){copy[k]=copy[k].concat(extraCopy[k]);});
var vatLabels={fr:'TVA du plat (%)',en:'Dish tax (%)',es:'IVA del plato (%)',it:'IVA del piatto (%)',de:'MwSt. des Gerichts (%)',nl:'Btw van het gerecht (%)',pt:'IVA do prato (%)'};keys.push('vat');Object.keys(copy).forEach(function(k){copy[k].push(vatLabels[k]);});
function lang(){return copy[w.LOCALE]?w.LOCALE:'fr';}function t(k){return copy[lang()][keys.indexOf(k)]||k;}
function esc(x){return String(x==null?'':x).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function n(x){return x===null||x===undefined||String(x).trim()===''?null:Number(String(x).replace(',','.'));}function money(x){return Number.isFinite(x)?x.toLocaleString(lang(),{style:'currency',currency:'EUR'}):'—';}function fmt(x){return Number.isFinite(x)?x.toLocaleString(lang(),{maximumFractionDigits:3}):'—';}
function db(){return w.DB;}function clone(x){return JSON.parse(JSON.stringify(x));}function uid(prefix){return prefix+Date.now().toString(36)+(++serial).toString(36);}
function date(){var a=new Date();return a.getFullYear()+'-'+String(a.getMonth()+1).padStart(2,'0')+'-'+String(a.getDate()).padStart(2,'0');}
function fresh(){return {name:'',product:'',price:'',grams:'',yield:'100',portions:'20',sell:'',tva:db()&&db().reg&&db().reg.tvac!=null?String(db().reg.tvac):'',supplier:'',reference:'',date:date(),side:'',sauce:'',sideName:'',sideCost:'',sauceName:'',sauceCost:'',extra:'0',stock:'',confirmed:false};}
function ensure(){if(state.db!==db()){state={db:db(),draft:fresh(),keep:null};}return state.draft;}
function active(p){return !p.cpArchived;}
